-- Claves de Data Protection en la base de datos: equivalente en Postgres/Supabase de la migración EF "AddDataProtectionKeys".
-- Con ellas la cookie de sesión y los tokens de Google cifrados sobreviven a los reinicios de la API en la nube y los
-- comparten todas las instancias. Se activa RLS sin políticas, como en el resto de tablas.

create table if not exists "DataProtectionKeys" (
  "Id" integer generated by default as identity primary key,
  "FriendlyName" text null,
  "Xml" text null
);

alter table "DataProtectionKeys" enable row level security;
